const headers = $json.headers || {};
const role = String(headers["x-user-role"] || "").trim().toLowerCase();
if (!role) {
  return { json: { statusCode: 401, error: "session_missing", code: "session_missing" } };
}
return {
  json: {
    action: $json.action,
    session: { role },
    params: $json.params || {},
    body: $json.body || {},
  },
};

// ============================================================
// Votes API — Airtable backend
//
// Airtable tables:
//   VoteQuestions : id (formula → "vq_recXXX"), question (text), options (text/JSON), active (checkbox)
//   VoteResults   : question (linked to VoteQuestions), option (text), count (number)
//
// GET /votes  → { questions: [{ id, question, options, results, total }] }
// POST /votes/:question_id  body { option } → { ok: true }
// ============================================================

const CONFIG = {
  AIRTABLE_PAT: "REDACTED_SET_IN_N8N",
  AIRTABLE_BASE_ID: "appyUZ6ny7FTzPKSk",
  QUESTIONS_TABLE: "VoteQuestions",
  RESULTS_TABLE: "VoteResults",
};

const request = this.helpers.httpRequest.bind(this.helpers);
const apiKey = String(CONFIG.AIRTABLE_PAT || "").trim();
const baseId = String(CONFIG.AIRTABLE_BASE_ID || "").trim();

if (!apiKey || !baseId) {
  return { json: { statusCode: 500, error: "Airtable config missing in n8n environment", code: "airtable_config_missing" } };
}

const airtable = "https://api.airtable.com/v0/" + baseId;
const headers = { Authorization: "Bearer " + apiKey };
const action = String($json.action || "");
const body = $json.body || {};
const params = $json.params || {};
const QT = encodeURIComponent(CONFIG.QUESTIONS_TABLE);
const RT = encodeURIComponent(CONFIG.RESULTS_TABLE);

const esc = (v) => String(v || "").replace(/'/g, "\\'");

// ─── GET /votes ──────────────────────────────────────────────
if (action === "list") {
  // 1. Fetch all active questions (id is a formula field like "vq_recXXX")
  const qData = await request({
    method: "GET",
    url: airtable + "/" + QT + "?filterByFormula=" + encodeURIComponent("{active}=1") + "&fields%5B%5D=id&fields%5B%5D=question&fields%5B%5D=options",
    headers,
    json: true,
  });

  const qRecords = qData.records || [];
  if (qRecords.length === 0) {
    return { json: { questions: [] } };
  }

  // 2. For each question fetch its VoteResults (question is a linked field → filter by Airtable record ID)
  const questions = [];
  for (const q of qRecords) {
    const airtableId = q.id; // "recXXX"
    const customId = String(q.fields.id || q.id); // "vq_recXXX"
    let options = [];
    try { options = JSON.parse(q.fields.options || "[]"); } catch (_) {}

    let rRecords = [];
    try {
      const rData = await request({
        method: "GET",
        url: airtable + "/" + RT + "?filterByFormula=" + encodeURIComponent("FIND('" + airtableId + "', ARRAYJOIN({question}))") + "&fields%5B%5D=option&fields%5B%5D=count",
        headers,
        json: true,
      });
      rRecords = rData.records || [];
    } catch (_) {}

    const results = {};
    let total = 0;
    for (const r of rRecords) {
      const opt = String(r.fields.option || "");
      const cnt = Number(r.fields.count || 0);
      results[opt] = cnt;
      total += cnt;
    }

    questions.push({ id: customId, question: String(q.fields.question || ""), options, results, total });
  }

  return { json: { questions } };
}

// ─── POST /votes/:question_id ─────────────────────────────────
if (action === "cast") {
  const questionId = String(params.question_id || "").trim();
  const option = String(body.option || "").trim();

  if (!questionId || !option) {
    return { json: { statusCode: 400, error: "question_id and option are required", code: "vote_invalid" } };
  }

  // 1. Find question by its formula id field ("vq_recXXX")
  const qData = await request({
    method: "GET",
    url: airtable + "/" + QT + "?filterByFormula=" + encodeURIComponent("AND({id}='" + esc(questionId) + "',{active}=1)") + "&maxRecords=1&fields%5B%5D=id&fields%5B%5D=options",
    headers,
    json: true,
  });

  const question = (qData.records || [])[0];
  if (!question) {
    return { json: { statusCode: 404, error: "Question not found or inactive", code: "vote_question_missing" } };
  }

  const airtableId = question.id; // "recXXX" — used for linking in VoteResults

  let options = [];
  try { options = JSON.parse(question.fields.options || "[]"); } catch (_) {}
  if (!options.includes(option)) {
    return { json: { statusCode: 400, error: "Invalid option", code: "vote_option_invalid" } };
  }

  // 2. Find existing VoteResults row (question is a linked field)
  const rData = await request({
    method: "GET",
    url: airtable + "/" + RT + "?filterByFormula=" + encodeURIComponent("AND(FIND('" + airtableId + "', ARRAYJOIN({question})),{option}='" + esc(option) + "')") + "&maxRecords=1&fields%5B%5D=count",
    headers,
    json: true,
  });

  const existing = (rData.records || [])[0];

  if (existing) {
    // 3a. Increment
    await request({
      method: "PATCH",
      url: airtable + "/" + RT + "/" + existing.id,
      headers,
      body: { fields: { count: (Number(existing.fields.count) || 0) + 1 } },
      json: true,
    });
  } else {
    // 3b. Create new row — link question as array of Airtable record IDs
    await request({
      method: "POST",
      url: airtable + "/" + RT,
      headers,
      body: { fields: { question: [airtableId], option, count: 1 } },
      json: true,
    });
  }

  return { json: { ok: true } };
}

return { json: { statusCode: 404, error: "unknown votes action", code: "votes_action_missing" } };
